<div class="form-panel"><form method="get" class="filter-form"><input type="hidden" name="page" value="<?=e($listingPage)?>">
<?php foreach($listingFields as $key=>$field): ?><label><?=e($field['label'])?><?php if(isset($field['options'])): ?><select name="<?=e($key)?>"><option value="">Todos</option><?php foreach($field['options'] as $value=>$label): ?><option value="<?=e($value)?>" <?=listingText($_GET,$key)===(string)$value?'selected':''?>><?=e($label)?></option><?php endforeach; ?></select><?php else: ?><input name="<?=e($key)?>" type="<?=e($field['type']??'text')?>" value="<?=e(listingText($_GET,$key))?>" maxlength="180"><?php endif; ?></label><?php endforeach; ?>
<button class="button secondary">Consultar</button><a class="text-link" href="/?page=<?=e($listingPage)?>">Limpiar filtros</a></form></div>
